import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Developer Monthly 2021-05-05","description":"","frontmatter":{"title":"Ceph Developer Monthly 2021-05-05","date":"2021-05-05T00:00:00.000Z","updated":"2021-05-07T00:00:00.000Z","tags":["Ceph","分布式存储","OSD Map优化","客户端使用效率","灾难恢复","集群隔离"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Monthly_2021-05-05.md","filePath":"posts/2021/Ceph_Developer_Monthly_2021-05-05.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Developer_Monthly_2021-05-05.md"};function i(p,e,n,s,h,d){return t(),l("div",null,[...e[0]||(e[0]=[o('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>在2021年5月5日的Ceph开发者月度会议中，主要讨论了以下议题：</p><h3 id="优化osd-map以提升客户端使用效率" tabindex="-1">优化OSD Map以提升客户端使用效率 <a class="header-anchor" href="#优化osd-map以提升客户端使用效率" aria-label="Permalink to &quot;优化OSD Map以提升客户端使用效率&quot;">​</a></h3><ul><li><strong>问题</strong>：在高速集群中，客户端可能无法及时获取更新的OSD Map，导致使用过时的信息。</li><li><strong>解决方案</strong>：通过优化客户端请求OSD Map的行为，确保客户端只请求必要的版本，减少监控器的负担。此外，讨论了使用更轻量级的OSD Map版本，以减少传输数据量。</li></ul><h3 id="增加通过标签或生成号来阻止实体列表的功能" tabindex="-1">增加通过标签或生成号来阻止实体列表的功能 <a class="header-anchor" href="#增加通过标签或生成号来阻止实体列表的功能" aria-label="Permalink to &quot;增加通过标签或生成号来阻止实体列表的功能&quot;">​</a></h3><ul><li><strong>问题</strong>：在灾难恢复场景中，需要能够阻止整个集群或特定应用程序访问共享存储端点，以实现无缝切换。</li><li><strong>解决方案</strong>：讨论了通过标签或生成号来阻止实体列表的可行性，以及更简单的网络层阻止方案。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>更新客户端代码以优化OSD Map请求。</li><li>研究并实现IP范围阻止列表功能。</li><li>与社区进一步讨论和细化阻止实体列表的方案。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>审计现有客户端以确定其从OSD Map解码哪些部分。</li><li>探索创建仅包含客户端所需信息的OSD Map版本。</li><li>评估和实施网络层阻止方案。</li></ul><p>会议强调了优化Ceph存储系统性能和可靠性的重要性，并讨论了如何通过改进客户端行为和探索网络层阻止方案来实现这一目标。</p>',11)])])}const c=a(r,[["render",i]]);export{u as __pageData,c as default};
